insert into bit_faq (group_name, question, answer, sort_order, status) values ('Produkte & Sortiment', 'Welche Produkte bietet die BIT Bierther GmbH an?', 'Schrumpfschlauch, Isolierschlauch, Silikonschlauch, Glasseidenschlauch, Geflechtschlauch, Wellrohr, Kabelbinder sowie Verarbeitungsgeräte und weitere Zubehörprodukte.', 10, 'published');
insert into bit_faq (group_name, question, answer, sort_order, status) values ('Produkte & Sortiment', 'Für welche Branchen sind die Produkte geeignet?', 'Energietechnik / Erneuerbare Energien, Automotive, Hausgeräte, Medizintechnik, Maschinen- und Anlagenbau, Licht- und Beleuchtungstechnik sowie Sicherheitstechnik.', 20, 'published');
insert into bit_faq (group_name, question, answer, sort_order, status) values ('Produkte & Sortiment', 'Bieten Sie auch Schrumpfschlauch mit UL-Zulassung an?', 'Ja, verschiedene Schrumpf- und Isolierschläuche sind mit UL-Zulassung erhältlich.', 30, 'published');
insert into bit_faq (group_name, question, answer, sort_order, status) values ('Produkte & Sortiment', 'Gibt es Schrumpfschlauch in verschiedenen Farben oder transparent?', 'Ja, farbige und transparente Varianten sind Teil des Sortiments.', 40, 'published');
insert into bit_faq (group_name, question, answer, sort_order, status) values ('Konfektionierung & individuelle Lösungen', 'Kann ich Schrumpfschlauch nach individuellem Maß zuschneiden lassen?', 'Ja, Schrumpf- und Isolierschläuche werden auf Kundenwunsch abgelängt bzw. geschnitten.', 50, 'published');
insert into bit_faq (group_name, question, answer, sort_order, status) values ('Konfektionierung & individuelle Lösungen', 'Ist eine Bedruckung der Schläuche möglich?', 'Ja, zur Kennzeichnung von Kabeln und Leitungen können Schläuche individuell bedruckt und perforiert werden.', 60, 'published');
insert into bit_faq (group_name, question, answer, sort_order, status) values ('Konfektionierung & individuelle Lösungen', 'Bieten Sie individuelle Verpackungseinheiten oder eigene Etiketten an?', 'Ja, individuelle Verpackungen, Etiketten sowie Direktversand an Endkunden sind möglich.', 70, 'published');
insert into bit_faq (group_name, question, answer, sort_order, status) values ('Lieferung & Logistik', 'Wie schnell erfolgt die Lieferung von Standardartikeln?', 'In der Regel innerhalb von 24 Stunden.', 80, 'published');
insert into bit_faq (group_name, question, answer, sort_order, status) values ('Lieferung & Logistik', 'Ist auch eine Just-in-Time-Belieferung möglich?', 'Ja, neben Sofort-Bestellungen werden auch Termin- und Just-in-Time-Bestellungen angeboten.', 90, 'published');
insert into bit_faq (group_name, question, answer, sort_order, status) values ('Qualität & Zertifizierung', 'Welche Zertifizierungen hat die BIT Bierther GmbH?', 'DIN ISO 9001:2015 sowie UL-Zulassungen (UL File E196690 und E362210).', 100, 'published');
insert into bit_faq (group_name, question, answer, sort_order, status) values ('Qualität & Zertifizierung', 'Sind die Produkte REACH- und RoHS-konform?', 'Ja, alle Produkte entsprechen den REACH- und RoHS-Vorgaben.', 110, 'published');
insert into bit_faq (group_name, question, answer, sort_order, status) values ('Qualität & Zertifizierung', 'Wie wird die Produktqualität sichergestellt?', 'Durch laufende Kontrollen in Wareneingang, Produktion und Warenausgang sowie Dokumentation via Messprotokollen und Werksprüfzeugnissen.', 120, 'published');
insert into bit_faq (group_name, question, answer, sort_order, status) values ('Beratung & Kontakt', 'Gibt es einen festen Ansprechpartner für Anfragen?', 'Ja, Kunden erhalten feste Ansprechpartner für individuelle technische Beratung.', 130, 'published');
insert into bit_faq (group_name, question, answer, sort_order, status) values ('Beratung & Kontakt', 'Wie kann ich Kontakt aufnehmen?', 'Per Telefon, E-Mail oder über das Kontaktformular auf der Website (mit Kategorieauswahl je nach Produktbereich).', 140, 'published');
insert into bit_faq (group_name, question, answer, sort_order, status) values ('Beratung & Kontakt', 'Wie lange gibt es die BIT Bierther GmbH schon?', 'Seit fast 30 Jahren am Markt.', 150, 'published');
