insert into bit_jobs (slug, title, intro, body, tasks_title, tasks, closing, sort_order, status) values ('vertrieb', 'Verstärkung im Bereich Vertrieb*', 'Sie haben eine Leidenschaft für Kommunikation? Auf neue Menschen zuzugehen macht Ihnen Spaß? Sie zeichnet Offenheit und Dienstleistungsorientierung aus? Dann sind Sie genau, was wir suchen …', 'Bauen Sie Ihren eigenen Arbeitsbereich auf, in dem Sie Bestandskunden und die, die es noch werden wollen, bei der zukünftigen Zusammenarbeit betreuen.
insert into bit_jobs (slug, title, intro, body, tasks_title, tasks, closing, sort_order, status) values ('lagerist', 'Lagerist*', 'Sie packen gerne mit an, arbeiten sorgfältig und behalten auch bei vielen Aufträgen den Überblick? Dann verstärken Sie unser Lagerteam in Swisttal-Heimerzheim.', 'In unserem Lager sorgen Sie dafür, dass über 1.000 Standardartikel zuverlässig ihren Weg zum Kunden finden – in der Regel innerhalb von 24 Stunden.', 'Ihre Aufgaben:', ARRAY['Wareneingang inklusive Kontrolle und Einlagerung','Kommissionierung, Verpackung und Versand der Kundenaufträge','Unterstützung der Konfektionierung (Zuschnitt und Verpackungseinheiten)','Bestandspflege und Mitarbeit bei Inventuren']::text[], 'Erfahrung im Lager ist von Vorteil, ein Staplerschein wünschenswert – wichtiger sind uns Zuverlässigkeit, Sorgfalt und Teamgeist. Auch motivierte Quereinsteiger sind herzlich willkommen.', 20, 'published') on conflict (slug) do update set title=excluded.title, intro=excluded.intro, body=excluded.body, tasks_title=excluded.tasks_title, tasks=excluded.tasks, closing=excluded.closing, sort_order=excluded.sort_order, status=excluded.status;
insert into bit_jobs (slug, title, intro, body, tasks_title, tasks, closing, sort_order, status) values ('ausbildung', 'Ausbildung bei der BIT: Kaufmann/-frau für Groß- und Außenhandelsmanagement', 'Du willst nach der Schule richtig durchstarten? Bei uns lernst du den Großhandel von Grund auf – vom Einkauf über Vertrieb und Lagerlogistik bis zum Rechnungswesen.', 'Als Ausbildungsbetrieb seit der Gründung begleiten wir dich durch alle Abteilungen: Du übernimmst früh eigene Aufgaben, bekommst feste Ansprechpartner und arbeitest von Anfang an im Tagesgeschäft mit.', 'Das erwartet dich:', ARRAY['Einkauf, Vertrieb, Auftragsbearbeitung und Disposition kennenlernen','Kundenanfragen, Angebote und Aufträge selbstständig bearbeiten','Lagerlogistik und Warenwirtschaft in der Praxis erleben','Rechnungswesen und moderne Warenwirtschafts-IT']::text[], 'Die Ausbildung dauert in der Regel drei Jahre und findet im Wechsel mit der Berufsschule statt. Bei guter Leistung stehen die Chancen auf Übernahme sehr gut.', 30, 'published') on conflict (slug) do update set title=excluded.title, intro=excluded.intro, body=excluded.body, tasks_title=excluded.tasks_title, tasks=excluded.tasks, closing=excluded.closing, sort_order=excluded.sort_order, status=excluded.status;
